<?php require_once __DIR__.'/bootstrap.php';require_login();$id=(int)($_GET['id']??0);$ep=(float)($_GET['episode']??1);$s=$pdo->prepare('SELECT * FROM anime WHERE id=?');$s->execute([$id]);$a=$s->fetch();if(!$a)exit('Anime not found');$es=$pdo->prepare('SELECT * FROM episodes WHERE anime_id=? AND active=1 ORDER BY number');$es->execute([$id]);$episodes=$es->fetchAll();if(!$episodes) $episode=null; else {$episode=$episodes[0];foreach($episodes as $x)if((float)$x['number']===$ep)$episode=$x;}$sources=[];$languages=[];$selected=(string)($_GET['language']??'');if($episode){$q=$pdo->prepare('SELECT * FROM video_sources WHERE anime_id=? AND episode_id=? AND active=1 ORDER BY language,priority,server_name');$q->execute([$id,$episode['id']]);$sources=$q->fetchAll();$languages=array_values(array_unique(array_column($sources,'language')));if($selected!==''&&!in_array($selected,$languages,true))$selected='';if($selected==='')$selected=$languages[0]??'';}$filtered=array_values(array_filter($sources,fn($v)=>$v['language']===$selected));$server=(string)($_GET['server']??'');$current=$filtered[0]??null;foreach($filtered as $v)if($v['server_name']===$server)$current=$v;$index=-1;foreach($episodes as $k=>$x)if($episode&&$x['id']===$episode['id'])$index=$k;$prev=$index>0?$episodes[$index-1]:null;$next=$index>=0&&isset($episodes[$index+1])?$episodes[$index+1]:null;$title='Watch '.($a['title']??'Anime').' — AniRead';include __DIR__.'/includes/header.php';?><h1><?=e($a['title'])?> <span class="muted">Episode <?=e($episode['number']??$ep)?></span></h1><div class="actions"><?php if($prev):?><a class="btn alt" href="?id=<?=$id?>&episode=<?=urlencode($prev['number'])?>">Previous Episode</a><?php endif;if($next):?><a id="next-episode" class="btn alt" href="?id=<?=$id?>&episode=<?=urlencode($next['number'])?>">Next Episode</a><?php endif;?></div><br><?php if($current):?><div class="player"><?php if($current['source_type']==='iframe'):?><iframe src="<?=e($current['source_url'])?>" allow="autoplay; fullscreen" allowfullscreen></iframe><?php else:?><video id="video" controls autoplay playsinline src="<?=e($current['source_url'])?>"></video><?php endif;?></div><form class="filters" method="get"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="episode" value="<?=e($episode['number'])?>"><label>Language <select name="language" onchange="this.form.submit()"><?php foreach($languages as $l):?><option <?=selected($l,$selected)?>><?=e($l)?></option><?php endforeach;?></select></label><label>Server <select name="server" onchange="this.form.submit()"><?php foreach($filtered as $v):?><option value="<?=e($v['server_name'])?>" <?=selected($v['server_name'],$current['server_name'])?>><?=e($v['server_name'])?></option><?php endforeach;?></select></label></form><script>const n=document.getElementById('next-episode'),v=document.getElementById('video');if(v&&n)v.addEventListener('ended',()=>{if(localStorage.getItem('anireadAutoNext')!=='0')location.href=n.href});</script><?php else:?><div class="form"><h2>Streaming source unavailable for this episode.</h2><p class="muted">No active authorized source is configured for this episode.</p></div><?php endif;?><section class="section"><h2>Episodes</h2><div class="episode-list"><?php foreach($episodes as $x):?><a href="?id=<?=$id?>&episode=<?=urlencode($x['number'])?>">Episode <?=e($x['number'])?></a><?php endforeach;?></div></section><?php if($episode){$h=$pdo->prepare('INSERT INTO watch_history(user_id,anime_id,episode_number,updated_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE episode_number=VALUES(episode_number),updated_at=NOW()');$h->execute([user()['id'],$id,$episode['number']]);}include __DIR__.'/includes/footer.php';
